#pragma once

#include <string>

class House {
private:
    int numRooms;
    const int maxCapacity;
    std::string& ownerName;
    // `const` and reference members require initialization list in constructor

public:
    // Constructor using member initialization list
    House(int rooms, int capacity, std::string& owner);

    // Explicitly requesting default destructor generated by compiler
    ~House() = default;

    // Explicitly disallow compiler-generated copy functions
    House(const House&) = delete;
    House& operator=(const House&) = delete;

    void printDetails() const;
};
